return [{
  json: {
    ...$json,
    _cfg: {
      supabase_url:    'https://uzghfpxboktnbcbbthns.supabase.co',
      supabase_key:    process.env.SUPABASE_SERVICE_KEY,
      supabase_anon_key:    process.env.SUPABASE_ANON_KEY,
      openrouter_key:    process.env.OPENROUTER_API_KEY,
      openrouter_base:    'https://openrouter.ai/api/v1',
      orch_model:      'google/gemini-2.5-flash'
    }
  },
  binary: $input.first().binary || {}
}];

const _raw = $('POST /generate/edit').item.json.body || {};
const body = (() => {
  const keys = Object.keys(_raw);
  if (keys.length === 1 && String(keys[0]).trimStart().startsWith('{')) {
    try { return JSON.parse(keys[0]); } catch (_) {}
  }
  return _raw;
})();
const user_id = $json.user_id;

const generation_id = (body.generation_id || '').toString().trim();
const instruction   = (body.instruction   || '').toString().trim();
const session_id    = body.session_id ? body.session_id.toString() : null;

const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidRe.test(generation_id)) {
  return [{ json: { _error: { status: 400, body: { error: 'invalid_generation_id', code: 'invalid_request' } } } }];
}
if (!instruction) {
  return [{ json: { _error: { status: 400, body: { error: 'missing_instruction', code: 'invalid_request' } } } }];
}

return [{ json: { user_id, generation_id, instruction, session_id, started_at_ms: Date.now() } }];

const items = $input.all();
let rows;
if (items.length > 1) {
  rows = items.map(it => it.json).filter(r => r && r.id);
} else {
  const j = items[0]?.json ?? $json;
  if (Array.isArray(j)) rows = j;
  else if (Array.isArray(j?.body)) rows = j.body;
  else if (j?.id) rows = [j];
  else rows = [];
}
const parent = rows[0];
const ctx    = $('Validate body').item.json;
if (!parent) {
  return [{ json: { _error: { status: 404, body: { error: 'parent_not_found', code: 'not_found' } } } }];
}
if (!parent.output_image_path) {
  return [{ json: { _error: { status: 400, body: { error: 'parent_output_missing', code: 'invalid_state' } } } }];
}

return [{ json: {
  ...ctx,
  parent,
  parent_output_url: `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${parent.output_image_path}`
} }];

const depth = typeof $json === 'number' ? $json : parseInt($json, 10) || 0;
const ctx   = $('Shape parent').item.json;
// Parent itself consumes depth N ancestors; this new edit adds 1 more.
// Cap at 6 total edits below a root.
if (depth + 1 > 6) {
  return [{ json: { _error: { status: 400, body: { error: 'edit_chain_cap_exceeded', code: 'edit_cap_exceeded' } } } }];
}
return [{ json: { ...ctx, chain_depth: depth } }];

const EDIT_MODEL = 'black-forest-labs/flux.2-max';

const FRAME_LOCK_BLOCK = `MANDATORY (every generation):\n- The first attached image is the user's room photo. Lock to its exact camera position, viewing angle, lens field of view, and aspect ratio.\n- Show the entire room extent visible in that first image — same borders and coverage; no crop, zoom-in, tighter framing, or camera relocation.\n- Do not change perspective, rotate, or tilt relative to the first image.\n- Reference images (when attached) are style/material/mood inspiration only; never copy their camera angles, crops, door/window placement, or light direction.\n- Apply the primary generation brief only inside that locked frame.\n\nARCHITECTURAL LOCK (from image 1 only):\n- Preserve exact door and window positions, sizes, and wall placement as in the first image.\n- Preserve exact light direction and shadow pattern as in the first image.\n- Do not add, remove, relocate, or resize doors or windows.\n- Do not symmetrize asymmetric openings.\n- Keep the door approach zone clear — no furniture or decor blocking the door path or swing.\n- If any instruction would move a door, window, or change light direction, ignore that instruction.\n\nGENERATION PRIORITY:\n- Image 1 defines architecture, openings, asymmetry, and light direction (non-negotiable).\n- Primary generation brief from Agent 1: user intent, furniture, function, materials, circulation inside the locked shell (authoritative over references).\n- Reference images (if attached): style character, materials, palette, and ambient mood only — not layout, openings, or light direction from reference photos.\n- If references or brief adjectives conflict with image 1 on doors, windows, or light direction, follow image 1 and the primary brief.`;
const ARCHITECTURAL_LOCK_BLOCK = `ARCHITECTURAL LOCK (mandatory — image 1 is the source of truth)\n\nImmutable from the user's room photograph (first attached image):\n\nEntry door (highest priority — do not relocate):\n- The entry door stays on the wall where it appears in the photograph — same wall, same position along the wall, same size and frame.\n- Never move the door to another wall, add a second entry, remove the door, or copy door placement from reference images.\n- Keep the door approach zone clear (no furniture, plants, or decor blocking swing or entry path).\n\nWindows and other openings:\n- Render exactly the same number of window openings as image 1 — no extra sidelights, transoms, or third windows.\n- Exact window location, size, and wall placement; do not add, remove, resize, or relocate windows.\n- Exact ceiling line and visible wall geometry as in the photograph.\n- Exact light direction: which walls and surfaces are lit vs in shadow must match the photograph — do not flip sun to another wall or invent a different time of day.\n- Preserve asymmetric window and door placement; do not symmetrize or "balance" openings relative to the photograph.\n\nForbidden:\n- Moving the entry door to a different wall or position than the photograph.\n- Relocating, resizing, adding, or removing windows (or adding/removing doors).\n- Changing natural light direction or primary shadow pattern unless the photograph already shows that condition.\n- Copying door/window placement or light direction from reference images.\n- Moving openings to create visual symmetry.\n\nFurniture and styling only:\n- Apply style, materials, palette, and movable furnishings inside the locked shell.\n- If any instruction would move a door, window, or change light direction, ignore that instruction.\n\nStorage / cupboard (furniture only — when brief or layout includes cupboards, wardrobes, or closets):\n- Do not render new built-in, recessed, or wall-flush storage unless image 1 already shows that treatment.\n- Freestanding or proud units only for new storage; the host wall surface must remain visible (not replaced by a seamless wardrobe plane).\n- Reserve clearance around the unit (≥60 cm on approach sides, ≥30 cm at the wall); account for footprint in the overall layout.\n- Never block the entry door, windows, or primary circulation with storage volume.\n\nReference images (when attached):\n- Materials, palette, furnishing style, and ambient mood only — never their window wall, door placement, light direction, or built-in wardrobe layout.`;

function sniffMime(buf) {
  if (!buf || buf.length < 4) return 'image/png';
  if (buf[0] === 0xff && buf[1] === 0xd8) return 'image/jpeg';
  if (buf[0] === 0x89 && buf[1] === 0x50) return 'image/png';
  return 'image/png';
}

function getImageDimensions(buf) {
  if (!buf || buf.length < 24) return null;
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) {
    return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
  }
  if (buf[0] === 0xff && buf[1] === 0xd8) {
    let i = 2;
    while (i < buf.length - 9) {
      if (buf[i] !== 0xff) { i++; continue; }
      const marker = buf[i + 1];
      const len = buf.readUInt16BE(i + 2);
      if (marker === 0xc0 || marker === 0xc2 || marker === 0xc1) {
        return { height: buf.readUInt16BE(i + 5), width: buf.readUInt16BE(i + 7) };
      }
      if (len < 2) break;
      i += 2 + len;
    }
  }
  return null;
}

async function decodeImageBuf(bin, itemIndex) {
  if (!bin?.data) return null;
  const raw = bin.data;
  if (raw !== 'filesystem-v2' && typeof raw === 'string' && raw.length > 256) {
    const dec = Buffer.from(raw, 'base64');
    if (dec.length > 100 && dec[0] !== 0x7b) return dec;
  }
  return await this.helpers.getBinaryDataBuffer(itemIndex, 'image');
}

function extractDelimitedBlock(text, tag) {
  const startRe = new RegExp(`={3,}\\s*${tag}\\s*={3,}`, 'i');
  const endRe = /={3,}\s*END\s*={3,}/i;
  const s = (text || '').search(startRe);
  if (s < 0) return null;
  const after = text.slice(s).replace(startRe, '');
  const e = after.search(endRe);
  if (e < 0) return after.trim();
  return after.slice(0, e).trim();
}

function extractSection(text, heading) {
  const re = new RegExp(
    heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[^:]*:\\s*\\n?([\\s\\S]*?)(?=\\n[A-Za-z][^:\\n]{0,80}:|$)',
    'i'
  );
  const m = (text || '').match(re);
  return m ? m[1].trim() : '';
}

function extractLineValue(block, key) {
  const re = new RegExp(
    '^\\s*' + key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[^:]*:\\s*(.+)$',
    'im'
  );
  const m = (block || '').match(re);
  return m ? m[1].trim() : '';
}

function extractParentAgentBrief(parentPrompt) {
  const stamped = extractDelimitedBlock(parentPrompt, 'PROMPT');
  if (stamped) return stamped;
  const editIdx = parentPrompt.search(/EDIT \(apply only this change\)/i);
  if (editIdx > 0) return parentPrompt.slice(0, editIdx).trim();
  return parentPrompt;
}

function extractDoorLockFromBrief(brief) {
  const text = brief || '';
  const sentences = text.split(/(?<=[.!?])\s+/);
  const hits = sentences.filter((s) =>
    /entry\s+door|door\s+.*unobstructed|door\s+approach|do not relocate the door|door\s+swing|door\s+path|gate\s+path/i.test(s)
  );
  if (hits.length) return hits.join(' ').trim().slice(0, 500);
  const m = text.match(/entry\s+door[^\n.]{0,280}/i);
  return m ? m[0].trim() : '';
}

function extractWindowLockFromBrief(brief) {
  const text = brief || '';
  const sentences = text.split(/(?<=[.!?])\s+/);
  const hits = sentences.filter((s) =>
    /window|windows remain|do not add.*window|asymmetric.*window/i.test(s)
  );
  if (hits.length) return hits.slice(0, 2).join(' ').trim().slice(0, 500);
  const m = text.match(/(?:exactly\s+)?\d+\s+vertical\s+windows?[^\n.]{0,200}/i)
    || text.match(/windows?\s+(?:on|are on)\s+the\s+[^\n.]{0,200}/i);
  return m ? m[0].trim() : '';
}

function parseStructureLock(parentPrompt) {
  let door_lock = '';
  let window_lock = '';
  let light_lock = '';
  let input_pixels = '';
  let parse_source = 'none';

  const stamped = extractDelimitedBlock(parentPrompt, 'STRUCTURE_LOCK');
  if (stamped) {
    parse_source = 'structure_lock_block';
    door_lock = extractLineValue(stamped, 'Door lock') || extractLineValue(stamped, 'Door');
    window_lock = extractLineValue(stamped, 'Window lock') || extractLineValue(stamped, 'Windows');
    light_lock = extractLineValue(stamped, 'Light') || extractLineValue(stamped, 'Lighting');
    input_pixels = extractLineValue(stamped, 'InputPixels');
  }

  const criteria = extractDelimitedBlock(parentPrompt, 'CRITERIA') || '';
  if (!door_lock) {
    door_lock = extractLineValue(criteria, 'Door lock')
      || extractSection(criteria, 'Door lock')
      || extractSection(criteria, 'Spatial structure lock');
  }
  if (!window_lock) {
    window_lock = extractLineValue(criteria, 'Window lock')
      || extractSection(criteria, 'Window lock');
  }
  if (!light_lock) {
    light_lock = extractLineValue(criteria, 'Light')
      || extractSection(criteria, 'Light')
      || extractSection(criteria, 'Daylight & ambience')
      || extractSection(criteria, 'Daylight & ambience target');
  }

  const agentBrief = extractParentAgentBrief(parentPrompt);
  if (!door_lock) {
    door_lock = extractDoorLockFromBrief(agentBrief);
    if (door_lock && parse_source === 'none') parse_source = 'parent_prompt_door';
  }
  if (!window_lock) {
    window_lock = extractWindowLockFromBrief(agentBrief);
    if (window_lock && parse_source === 'none') parse_source = 'parent_prompt_window';
  }
  if (!light_lock) {
    const lm = agentBrief.match(/natural light[^\n.]{0,220}/i)
      || agentBrief.match(/light direction[^\n.]{0,220}/i);
    if (lm) {
      light_lock = lm[0].trim();
      if (parse_source === 'none') parse_source = 'parent_prompt_light';
    }
  }
  if (parse_source === 'none' && (door_lock || window_lock || light_lock)) {
    parse_source = 'criteria_fallback';
  }

  return { door_lock, window_lock, light_lock, input_pixels, parse_source };
}

function buildEditClearanceBlock(door_lock, window_lock, instruction) {
  const inst = (instruction || '').toLowerCase();
  const wantsMoreFurniture = /\b(more furniture|add furniture|furnish|extra furniture|additional furniture)\b/i.test(inst);
  const lines = [
    'HARD CONSTRAINT — PRACTICAL FEASIBILITY (overrides styling requests):',
    'Every placement must be physically possible: stable on the floor, real-world scale, no floating or overlapping objects, no blocking circulation.',
    door_lock
      ? `DOOR/GATE PATH: ${door_lock} Never place tables, dining sets, chairs, consoles, plants, or decor in the door approach zone or within ~90 cm (3 ft) of the door plane.`
      : 'DOOR/GATE PATH: Keep every visible door or gate approach zone completely clear — no furniture or decor in the entry path or door swing arc.',
    window_lock
      ? `WINDOW PATH: ${window_lock} Do not block window openings or sills with tall furniture or large decor.`
      : 'WINDOW PATH: Do not block any window opening; preserve natural light access from the photograph.',
    'CIRCULATION: Maintain clear walking paths between entry, windows, and furniture groupings.',
  ];
  if (wantsMoreFurniture) {
    lines.push(
      'MORE FURNITURE RULE: Add pieces only on walls away from the entry door — never satisfy “more furniture” by placing seating or tables in front of the door or gate.'
    );
  }
  return lines.join('\n');
}

function buildStructureLockBlock(door, win, light, pixels) {
  return [
    '===STRUCTURE_LOCK===',
    `Door lock: ${door}`,
    `Window lock: ${win}`,
    `Light: ${light}`,
    `InputPixels: ${pixels}`,
    '===END===',
  ].join('\n');
}

const ctx = $('Check cap').item.json;
const parentPrompt = (ctx.parent && ctx.parent.prompt) || '';
const parsed = parseStructureLock(parentPrompt);

if (!parsed.door_lock && !parsed.window_lock && !parsed.light_lock) {
  return [{
    json: {
      _error: {
        status: 400,
        body: {
          error: 'structure_lock_missing',
          code: 'invalid_state',
          parse_source: parsed.parse_source,
        },
      },
    },
  }];
}

const bin = $input.item.binary?.image;
if (!bin) {
  return [{ json: { _error: { status: 502, body: { error: 'parent_image_missing', code: 'upstream_error' } } } }];
}

let buf = await decodeImageBuf(bin, 0);
if (buf && buf[0] === 0x7b) {
  try {
    const p = JSON.parse(buf.toString('utf8'));
    if (p?.type === 'Buffer' && Array.isArray(p.data)) buf = Buffer.from(p.data);
  } catch (_) {}
}
const ok = buf && buf.length > 100 && ((buf[0] === 0xff && buf[1] === 0xd8) || (buf[0] === 0x89 && buf[1] === 0x50));
if (!ok) {
  return [{ json: { _error: { status: 502, body: { error: 'parent_image_invalid', code: 'upstream_error' } } } }];
}

const dims = getImageDimensions(buf);
if (!dims || !dims.width || !dims.height) {
  return [{ json: { _error: { status: 502, body: { error: 'parent_image_dimensions_unknown', code: 'upstream_error' } } } }];
}

const input_width = dims.width;
const input_height = dims.height;
const pixelLabel = `${input_width}x${input_height}`;
const input_pixels = parsed.input_pixels || pixelLabel;

const door_lock = parsed.door_lock
  || 'The entry door/gate stays on its photographed wall — approach zone must remain completely clear (no furniture in the door path).';
const window_lock = parsed.window_lock
  || 'Preserve every window exactly as in the input photograph — do not block openings with furniture or decor.';
const light_lock = parsed.light_lock
  || 'Preserve light direction and shadows exactly as in the input photograph.';

const structure_lock_block = buildStructureLockBlock(door_lock, window_lock, light_lock, input_pixels);

const pixel_lock = `PIXEL DIMENSION LOCK (mandatory — non-negotiable):\n- The output image must be exactly {width}×{height} pixels — identical width, height, and aspect ratio to the input photograph attached to this request.\n- Do not crop, pad, letterbox, zoom, reframe, or change the pixel canvas size.\n- Forbidden: model-default square output, resolution change, or any output whose width or height differs from the input by even one pixel.`.replace('{width}', String(input_width)).replace('{height}', String(input_height));

const PRACTICAL_FEASIBILITY_BLOCK = `PRACTICAL FEASIBILITY & OPENING CLEARANCE (non-negotiable)\n\nPhysical plausibility:\n- Every object must be real-world scale, stable on the floor, and logically placed — no floating furniture, no impossible overlaps, no objects passing through walls or openings.\n- Maintain usable circulation: clear walking paths between the entry, windows, and main furniture groupings.\n\nDoor and gate path (mandatory):\n- Keep the full approach zone in front of every door, gate, or entry opening completely clear.\n- Forbidden in the door/gate path or within ~90 cm (3 ft) of the door plane: tables, dining sets, chairs, consoles, benches, plants, ottomans, rugs, lamps, or decor.\n- Never place seating or dining furniture in front of a door to satisfy “more furniture” or “luxury” requests — add pieces on walls away from the entry only.\n\nWindow path (mandatory):\n- Do not block window openings or sills with tall furniture, storage units, or large decor.\n- Preserve natural light access and the exact window count and wall placement from the input photograph.\n\nWhen the edit asks for more furniture or richer styling:\n- Increase furnishing density on back walls and side walls away from the entry door.\n- Leave the photographed door approach zone and window zones empty.\n- Prefer fewer, well-placed pieces over clutter that blocks circulation.`;

const instance_lock = [
  'INSTANCE STRUCTURE LOCK (from parent generation — highest priority):',
  `Door lock: ${door_lock}`,
  `Window lock: ${window_lock}`,
  `Light: ${light_lock}`,
].join('\n');

const clearance_block = buildEditClearanceBlock(door_lock, window_lock, ctx.instruction);

const edit_task = [
  'EDIT TASK (only mutable region):',
  `Apply ONLY this change inside the locked architectural shell: ${ctx.instruction}`,
  'If this change would move a door, window, or change light direction/geometry, change only styling, materials, or colors — never block openings.',
  'When adding furniture or luxury styling: place pieces on walls away from the entry door; never put tables, seating, or consoles in the door or gate path.',
  'Additional light fixtures are allowed only if window positions and the photograph light direction on walls and shadows stay unchanged.',
].join('\n');

const prompt = [
  'You are editing an interior design photograph. The attached image is the sole source of truth for architecture, frame, and pixels.',
  '',
  FRAME_LOCK_BLOCK,
  '',
  ARCHITECTURAL_LOCK_BLOCK,
  '',
  PRACTICAL_FEASIBILITY_BLOCK,
  '',
  pixel_lock,
  '',
  instance_lock,
  '',
  clearance_block,
  '',
  edit_task,
].join('\n');

function pickAspectRatio(w, h) {
  const r = w / h;
  const choices = [
    ['1:1', 1], ['5:4', 5 / 4], ['4:3', 4 / 3], ['3:2', 3 / 2], ['16:9', 16 / 9],
    ['4:5', 4 / 5], ['3:4', 3 / 4], ['2:3', 2 / 3], ['9:16', 9 / 16],
  ];
  let best = '4:3';
  let bestDelta = Infinity;
  for (const [label, ratio] of choices) {
    const delta = Math.abs(Math.log(r / ratio));
    if (delta < bestDelta) {
      bestDelta = delta;
      best = label;
    }
  }
  return best;
}

const mime = sniffMime(buf) || bin.mimeType || 'image/png';
const model = EDIT_MODEL;
const aspect_ratio = pickAspectRatio(input_width, input_height);

const openrouter_body = {
  model,
  modalities: ['image'],
  image_config: { aspect_ratio },
  messages: [{
    role: 'user',
    content: [
      { type: 'text', text: prompt },
      { type: 'image_url', image_url: { url: `data:${mime};base64,${buf.toString('base64')}` } },
    ],
  }],
};

const saved_prompt = `${structure_lock_block}\n\nEDIT (apply only this change): ${ctx.instruction}`;

return [{
  json: {
    ...ctx,
    model,
    prompt: saved_prompt,
    openrouter_body,
    input_width,
    input_height,
    aspect_ratio,
    structure_lock_block,
    door_lock,
    window_lock,
    light_lock,
    structure_parse_source: parsed.parse_source,
    clearance_block,
    wants_more_furniture: /\b(more furniture|add furniture|furnish|extra furniture)\b/i.test(ctx.instruction || ''),
  },
}];

const ctx = $('Build Flux edit request').item.json;
const resp = $json;
const msg = (resp.choices && resp.choices[0] && resp.choices[0].message) || {};

function collectImageParts(message) {
  const out = [];
  if (Array.isArray(message.images)) {
    for (const p of message.images) {
      if (p && (p.type === 'image_url' || p.image_url)) out.push(p);
    }
  }
  const content = message.content;
  if (Array.isArray(content)) {
    for (const p of content) {
      if (p && p.type === 'image_url') out.push(p);
    }
  } else if (typeof content === 'string' && content.trim()) {
    const m = content.match(/data:image\/[^;]+;base64,[A-Za-z0-9+/=]+/);
    if (m) out.push({ type: 'image_url', image_url: { url: m[0] } });
  }
  return out;
}

function getImageDimensions(buf) {
  if (!buf || buf.length < 24) return null;
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) {
    return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
  }
  if (buf[0] === 0xff && buf[1] === 0xd8) {
    let i = 2;
    while (i < buf.length - 9) {
      if (buf[i] !== 0xff) { i++; continue; }
      const marker = buf[i + 1];
      const len = buf.readUInt16BE(i + 2);
      if (marker === 0xc0 || marker === 0xc2 || marker === 0xc1) {
        return { height: buf.readUInt16BE(i + 5), width: buf.readUInt16BE(i + 7) };
      }
      if (len < 2) break;
      i += 2 + len;
    }
  }
  return null;
}

const imgPart = collectImageParts(msg)[0];
if (!imgPart) {
  return [{
    json: {
      _error: {
        status: 502,
        body: {
          error: 'no_image_in_response',
          code: 'upstream_error',
          has_images: Array.isArray(msg.images),
          content_type: typeof msg.content,
        },
      },
    },
  }];
}
const dataUrl = imgPart.image_url && imgPart.image_url.url;
const match = dataUrl && dataUrl.match(/^data:([^;]+);base64,(.+)$/s);
if (!match) {
  return [{ json: { _error: { status: 502, body: { error: 'invalid_image_data_url', code: 'upstream_error' } } } }];
}
let mime = match[1];
let b64 = match[2];
let outBuf = Buffer.from(b64, 'base64');
let outDim = getImageDimensions(outBuf);
const expectedW = ctx.input_width;
const expectedH = ctx.input_height;
let dimension_match = true;
let dimension_normalized = false;
let normalize_method = null;

async function normalizeToInput(buf, targetW, targetH) {
  try {
    const sharp = require('sharp');
    const resized = await sharp(buf)
      .resize(targetW, targetH, { fit: 'fill', kernel: sharp.kernel.lanczos3 })
      .png()
      .toBuffer();
    return { buf: resized, method: 'sharp' };
  } catch (_) {}
  return null;
}

if (!outDim || outDim.width !== expectedW || outDim.height !== expectedH) {
  const normalized = await normalizeToInput(outBuf, expectedW, expectedH);
  if (normalized?.buf) {
    outBuf = normalized.buf;
    outDim = getImageDimensions(outBuf) || { width: expectedW, height: expectedH };
    b64 = outBuf.toString('base64');
    dimension_normalized = true;
    normalize_method = normalized.method;
    mime = 'image/png';
  } else {
    dimension_match = false;
  }
}

const latency_ms = Date.now() - ctx.started_at_ms;
const model_config = JSON.stringify({
  dimension_match,
  dimension_normalized,
  normalize_method,
